	private static int[] intDestination(int rows, int stride) {
		int[] destination = new int[DESTINATION_OFFSET + rows * stride + 3];
		Arrays.fill(destination, INT_SENTINEL);
		return destination;
	}

	private static void assertLongBoundaries(long[] destination, int offset, int count) {
		assertEquals(LONG_SENTINEL, destination[offset - 1]);
		assertEquals(LONG_SENTINEL, destination[offset + count]);
	}

	private static Class<? extends Throwable> exceptionClass(Executable executable) {
		try {
			executable.execute();
		} catch (Throwable failure) {
			return failure.getClass();
		}
		throw new AssertionError("Expected an exception");
	}

	private static final class Fixture {

		private final int count;
		private final long[] subjects;
		private final long[] predicates;
		private final long[] objects;
		private final long[] contexts;

		private Fixture(int count) {
			this.count = count;
			int length = SOURCE_OFFSET + count + 3;
			subjects = new long[length];
			predicates = new long[length];
			objects = new long[length];
			contexts = new long[length];
			for (int index = 0; index < length; index++) {
				subjects[index] = value(index, 0x243f_6a88_85a3_08d3L);
				predicates[index] = value(index, 0x1319_8a2e_0370_7344L);
				objects[index] = value(index, 0xa409_3822_299f_31d0L);
				contexts[index] = index % 5 == 0 ? 0L : value(index, 0x082e_fa98_ec4e_6c89L);
			}
		}

		private long[] values(int component) {
			return switch (component) {
			case 0 -> subjects;
			case 1 -> predicates;
			case 2 -> objects;
			case 3 -> contexts;
			default -> throw new IllegalArgumentException("Unsupported component: " + component);
			};
		}

		private static long value(int index, long seed) {
			return FrontierStatisticsHash.mix64(seed + 0x9e37_79b9_7f4a_7c15L * (index + 1L));
		}
	}
